/* =========================================================================
 * PathFinder — Preloaded University Logos (inline base64 PNG, unchanged)
 * Recreates the hidden <div id="pf-uni-preload"> as the first element of
 * <body>, exactly where it lived in the single-file build. js/visualizers.js
 * reads these via document.querySelector('[data-uni-preload="<key>"]').
 * Must be loaded synchronously as the first child of <body>.
 * ========================================================================= */
(function () {
  var PF_UNI_LOGOS = [
    ["cmu", "data:image/png;base64,"],
    ["cu", "data:image/png;base64,"],
    ["kku", "data:image/png;base64,"],
    ["kmitl", "data:image/png;base64,"],
    ["kmutt", "data:image/png;base64,"],
    ["ku", "data:image/png;base64,"],
    ["mu", "data:image/png;base64,"],
    ["su", "data:image/png;base64,"],
    ["swu", "data:image/png;base64,"],
    ["tu", "data:image/png;base64,"]
  ];
  var script = document.currentScript;
  var wrap = document.createElement('div');
  wrap.id = 'pf-uni-preload';
  wrap.className = 'hidden';
  wrap.setAttribute('aria-hidden', 'true');
  PF_UNI_LOGOS.forEach(function (entry) {
    var img = document.createElement('img');
    img.setAttribute('data-uni-preload', entry[0]);
    img.setAttribute('src', entry[1]);
    img.setAttribute('alt', '');
    wrap.appendChild(img);
  });
  script.parentNode.insertBefore(wrap, script);
})();
